              <nav class="concept-context" aria-label="Current affiliations">
                <router-link :to="{ path: '/education', hash: '#study-hong-kong' }" aria-label="Read about Applied Artificial Intelligence at HKU"><span>Applied AI</span><strong>HKU</strong></router-link>
