        <router-link :to="{ path: '/research', hash: '#structure-settles-thought' }" data-story-reveal><span class="concept-current-number" aria-hidden="true">02</span><span class="concept-current-copy"><small>Research in progress</small><strong>Early Epistemic Settlement</strong></span><ArrowUpRightIcon /></router-link>
        <router-link :to="{ path: '/travels', hash: '#hong-kong' }" data-story-reveal><span class="concept-current-number" aria-hidden="true">03</span><span class="concept-current-copy"><small>Current location</small><strong>Hong Kong</strong></span><ArrowUpRightIcon /></router-link>
      </nav>
    </section>

    <AboutTab story />

  </main>
